
CREATE TABLE `dem_types` (
                             `id_` int NOT NULL AUTO_INCREMENT,
                             `parent` int NOT NULL DEFAULT '0',
                             `group` int NOT NULL DEFAULT '0',
                             `text_type` varchar(128) NOT NULL DEFAULT '',
                             `text_short_type` varchar(64) DEFAULT NULL,
                             `text_klaes` varchar(8) DEFAULT NULL,
                             `nost` binary(1) NOT NULL DEFAULT '0',
                             `icount` int NOT NULL DEFAULT '0',
                             `code1c` int NOT NULL DEFAULT '0',
                             `obj` varchar(32) DEFAULT NULL,
                             `prodarea` varchar(32) DEFAULT NULL,
                             `group_for_r_menu` int DEFAULT NULL,
                             PRIMARY KEY (`id_`),
                             KEY `group` (`group`),
                             KEY `text_klaes` (`text_klaes`),
                             KEY `prodarea` (`prodarea`),
                             KEY `obj` (`obj`),
                             KEY `text_type` (`text_type`),
                             KEY `text_short_type` (`text_short_type`)
) ENGINE=MyISAM AUTO_INCREMENT=308 DEFAULT CHARSET=cp1251;

